  "claims": [
    {
      "claim": "All visible L1 gold records report human oral bioavailability point/mean estimates above the 20% threshold (approximately 35% to >90%) for structurally related molecules, and none provides an affirmative F < 20% outcome.",
      "card_ids": ["C01","C02","C03","C04","C05","C06","C07","C08","C09","C10","C11","C12","C13","C14","C15","C16","C17","C18","C19","C20","C21","C22","C23","C24","C25"]
    },
    {
      "claim": "L4 permeability records for quinazoline and sulfonamide-containing analogs show high absorptive permeability: UK-294,315 Caco-2 A-B Papp was 10-15 ×10^-6 cm/s, nimesulide analogs gave A-B Papp of 2.7-3.4 ×10^-5 cm/s, and UK-343,664 rat ileum P_eff was 1.58 ×10^-5 cm/s, supporting intestinal absorption.",
      "card_ids": ["C111","C119","C104","C95","C123","C142"]
    },
    {
      "claim": "L4 solubility records for closely related quinazoline compounds (PRB 6 µg/mL; doxazosin mesylate 0.9-3.4 µg/mL) and other low-solubility drugs (vismodegib 1-3 µg/mL) indicate low aqueous solubility, but low solubility alone is not affirmative evidence for F < 20% and can be compatible with F >= 20% depending on dose and formulation.",
      "card_ids": ["C105","C131","C127","C135","C103","C98","C115","C96","C125"]
    },
    {
      "claim": "No L4 record provides a direct F < 20% outcome for the query or a close analog; the high prediction is retained.",
      "card_ids": ["C111","C119","C105"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C95","C96","C98","C101","C103","C104","C105","C111","C115","C119","C123","C125","C127","C131","C135","C142"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No query-specific solubility or permeability data; L4 records are analog-based with moderate transferability.",
    "No dose or formulation context for the query, so low aqueous solubility cannot be quantitatively linked to F < 20%.",
    "No matched oral versus IV exposure data for the query.",
    "No first-pass or systemic clearance data for the query; L5 may address gut-wall efflux and intestinal metabolism."
  ],
  "decision_summary": "Predicted high because all transferable L1 gold records and L3 oral-exposure records are consistent with F >= 20%, and L4 adds high Caco-2/rat ileum permeability for closely related quinazoline/sulfonamide analogs; low aqueous solubility records are a caveat but do not affirmatively establish F < 20% without dose/formulation context. Confidence remains moderate because evidence is analog-based and no direct query F measurement is available."
}

